//! The autohinter's styles, in `af_style_classes` order: each one's writing system, script (an index into `scripts.zig`), blue stringset (an index into `blues.zig`) and whether it takes the default coverage, as opposed to an OpenType feature's, which needs HarfBuzz. Data from FreeType 2.14.3 (tag `VER-2-14-3`) `src/autofit/afstyles.h`, `afws-iter.h` and `afblue.h`;
//! regenerate it from those files with every macro expanded (`AF_CONFIG_OPTION_CJK` and `AF_CONFIG_OPTION_INDIC` on, as FreeType builds by default) rather than editing it.

pub const WritingSystem = enum { dummy, latin, cjk, indic };

pub const Style = struct {
    name: []const u8,
    writing_system: WritingSystem,
    script: u8,
    blue_stringset: u16,
    default_coverage: bool,
};

